def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive integers in ``[start, finish]`` ending in ``s`` whose
    digits are all at most ``limit``.

    The suffix is fixed, so the only digits that need to be chosen are the
    digits preceding it.  For each possible total length, count those prefixes
    directly; on the length of the bound, a digit-by-digit count handles the
    upper-bound restriction.
    """
    if start > finish or finish < 1:
        return 0

    suffix = str(s)
    if not suffix or any(not ch.isdigit() or int(ch) > limit for ch in suffix):
        return 0

    def count_prefixes_at_most(cap: str) -> int:
        """Count legal, non-leading-zero prefixes of cap's length <= cap."""
        length = len(cap)
        total = 0
        for i, char in enumerate(cap):
            cap_digit = int(char)
            low = 1 if i == 0 else 0
            high = min(limit, cap_digit - 1)
            if high >= low:
                total += (high - low + 1) * (limit + 1) ** (length - i - 1)

            # Continue along the prefix equal to cap, if that digit is allowed.
            if cap_digit < low or cap_digit > limit:
                return total
        # The cap itself is a valid prefix.
        return total + 1

    def count_up_to(bound: int) -> int:
        if bound < 1:
            return 0
        bound_text = str(bound)
        bound_length = len(bound_text)
        suffix_length = len(suffix)
        if suffix_length > bound_length:
            return 0

        prefix_length = bound_length - suffix_length
        # All shorter lengths are unrestricted by the numeric bound.
        total = 0
        for length in range(prefix_length):
            if length == 0:
                # The suffix itself is a positive integer (as specified).
                total += 1
            else:
                total += limit * (limit + 1) ** (length - 1)

        cap_prefix = bound_text[:prefix_length]
        cap_suffix = bound_text[prefix_length:]
        if prefix_length == 0:
            # There is only one candidate of this length: s itself.
            if suffix <= cap_suffix:
                total += 1
        else:
            legal_cap = (
                cap_prefix[0] != "0"
                and all(int(ch) <= limit for ch in cap_prefix)
            )
            less_than_cap = count_prefixes_at_most(cap_prefix) - int(legal_cap)
            total += less_than_cap
            if legal_cap and suffix <= cap_suffix:
                total += 1
        return total

    return count_up_to(finish) - count_up_to(start - 1)
